 if(s.mode==='town'||s.returnMode==='town'){s.townPosition??={x:6,y:11};const p=s.townPosition;if(!p||!Number.isInteger(p.x)||!Number.isInteger(p.y)||p.x<1||p.x>11||p.y<1||p.y>12)throw Error('Invalid town position.');if(!townWalkable(p.x,p.y))s.townPosition={x:6,y:11};}
