function crossBorder(s,gate){const forward=gate.target>s.region;if(forward&&!DUNGEONS.filter(d=>d.region===s.region).every(d=>s.relics.includes(d.id))){s.flags.borderTauntPending=true;s.flags.borderVoice=Math.floor(rand(s)*3);note(s,'Three royal guards bar the gate. Recover both relics from this land before crossing. They introduce your head to a barrel of cold water.');return;}s.region=gate.target;s.x=forward?2:29;s.y=12;s.mode='world';s.dungeon=null;s.location=null;s.turns++;delete s.flags.borderTauntPending;note(s,'The gate opens. You cross into a new land.');if(s.region===1&&s.relics.length>=2)advance(s,5);if(s.region===2&&s.relics.length>=4)advance(s,9);if(s.region===3&&s.relics.length>=6)advance(s,13);}

